/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { enabledFlagNames } from './src/legacy-flags.js';
assert.deepEqual(enabledFlagNames([]), []);
assert.deepEqual(enabledFlagNames([{name:' beta ',enabled:true}]), ['beta']);
const values = [true, false, 1, 0, 'true', null, undefined, {}, new Boolean(true)];
assert.deepEqual(enabledFlagNames(values.map((enabled, i) => ({enabled, name: ' '+i+' '}))), ['0']);
assert.deepEqual(enabledFlagNames([{enabled:true,name:42},{enabled:true,name:null},{enabled:true,name:undefined},{enabled:true,name:' x '},{enabled:true,name:' x '}]), ['42','null','undefined','x','x']);
assert.deepEqual(enabledFlagNames(new Set([{enabled:true,name:' a '},{enabled:true,name:' b '}])), ['a','b']);
const events = [];
const flags = [0,1].map(i => ({
  get enabled() { events.push('enabled'+i); return true; },
  get name() { events.push('name'+i); return ' n'+i+' '; }
}));
assert.deepEqual(enabledFlagNames(flags), ['n0','n1']);
assert.deepEqual(events, ['enabled0','enabled1','name0','name1']);
const failure = new Error('enabled failure');
assert.throws(() => enabledFlagNames([{enabled:true,get name(){throw new Error('name failure');}},{get enabled(){throw failure;}}]), e => e === failure);
assert.deepEqual(enabledFlagNames([{enabled:false,get name(){throw new Error('must not read');}}]), []);
assert.throws(() => enabledFlagNames(null), TypeError);
assert.throws(() => enabledFlagNames([null]), TypeError);
console.log('Inline characterization checks passed.');
NODE"

